import { Component, ComponentInterface, Element, h, Host, Prop, State, Watch } from '@stencil/core';
import { handleAutofocus } from '../../utils/autofocus';
import { breakpointMapping } from '../../utils/breakpoint-mapping';

/**
 * @slot content - content slot of the page, will be wrapped in a <main> HTML tag
 */
@Component({
  tag: 'groupui-page',
  styleUrl: 'page.scss',
  shadow: true,
})
export class Page implements ComponentInterface {
  /**
   * switches background color to base variant
   */
  @Prop({ reflect: true }) readonly baseBackground: boolean;

  @State() isMobileLayoutVisible: boolean;

  @Element() host: HTMLElement;

  private firstLevel: 'top' | 'side';
  private secondLevel: 'top' | 'side' | '';
  private thirdLevel: 'top' | 'side' | '';
  private size: 'l' | '';

  private resizeObserver: ResizeObserver;

  @Watch('isMobileLayoutVisible')
  onIsMobileLayoutVisibleChanged() {
    if (this.isMobileLayoutVisible) {
      this.host.classList.add('mobile');
    } else {
      this.host.classList.remove('mobile');
    }
  }

  componentDidLoad(): void {
    handleAutofocus(this.host);

    const globalTopNav = this.getGlobalTopNavigation();
    const globalSideNav = this.getGlobalSideNavigation();
    let breakpoint: number;
    if (globalSideNav) {
      breakpoint = globalSideNav.customBreakpoint ?? breakpointMapping.get(globalSideNav.breakpoint);
    }
    if (globalTopNav) {
      breakpoint = globalTopNav.customBreakpoint ?? breakpointMapping.get(globalTopNav.breakpoint);
    }
    if (breakpoint) {
      this.addResizeObserver(breakpoint);
    }
  }

  componentWillLoad(): void {
    this.assignGlobalNav();
    this.assignLocalNavs();
  }

  private addResizeObserver(breakpoint: number) {
    this.resizeObserver = new ResizeObserver((element) => {
      this.isMobileLayoutVisible = element[0].contentRect.width < breakpoint;
    });

    this.resizeObserver?.observe(window.document.documentElement);
  }

  private getGlobalTopNavigation(): HTMLGroupuiGlobalTopNavigationElement | null {
    return this.host.querySelector('groupui-global-top-navigation');
  }

  private getGlobalSideNavigation(): HTMLGroupuiGlobalSideNavigationElement | null {
    return this.host.querySelector('groupui-global-side-navigation');
  }

  private assignGlobalNav(): void {
    const topNav = this.host.querySelector('groupui-global-top-navigation');
    const sideNav = this.host.querySelector('groupui-global-side-navigation');
    if (!topNav && !sideNav) {
      return;
    }

    if (topNav) {
      topNav.setAttribute('slot', 'global-nav');
      this.firstLevel = 'top';
    } else {
      sideNav.setAttribute('slot', 'global-nav');
      this.firstLevel = 'side';
    }
  }

  private assignLocalNavs(): void {
    const topNav = this.host.querySelector('groupui-local-top-navigation');
    const sideNav = this.host.querySelector('groupui-local-side-navigation');
    if (!topNav && !sideNav) {
      this.secondLevel = '';
      this.thirdLevel = '';
      this.size = '';
      return;
    }

    if (topNav && !sideNav) {
      topNav.setAttribute('slot', 'first-local-nav');
      this.secondLevel = 'top';
      this.thirdLevel = '';
      this.size = topNav.size === 'l' ? 'l' : '';
      return;
    } else if (!topNav && sideNav) {
      sideNav.setAttribute('slot', 'first-local-nav');
      this.secondLevel = 'side';
      this.thirdLevel = '';
      this.size = '';
      return;
    }
    this.assignBothLocalNavs(topNav, sideNav);
  }

  private assignBothLocalNavs(
    topNav: HTMLGroupuiLocalTopNavigationElement,
    sideNav: HTMLGroupuiLocalSideNavigationElement
  ): void {
    const nodeNames = Array.from(this.host.childNodes).map((n) => n.nodeName);
    const sideName = 'GROUPUI-LOCAL-SIDE-NAVIGATION';
    const topName = 'GROUPUI-LOCAL-TOP-NAVIGATION';
    this.size = topNav.getAttribute('size') === 'l' ? 'l' : '';
    if (nodeNames.indexOf(sideName) < nodeNames.indexOf(topName)) {
      sideNav.setAttribute('slot', 'first-local-nav');
      topNav.setAttribute('slot', 'second-local-nav');
      this.secondLevel = 'side';
      this.thirdLevel = 'top';
    } else {
      topNav.setAttribute('slot', 'first-local-nav');
      sideNav.setAttribute('slot', 'second-local-nav');
      this.secondLevel = 'top';
      this.thirdLevel = 'side';
    }
  }

  disconnectedCallback() {
    this.resizeObserver?.disconnect();
  }

  render() {
    const navCombination = [this.firstLevel, this.secondLevel, this.thirdLevel, this.size]
      .filter((l) => l !== '')
      .join('-');

    return (
      <Host class={navCombination}>
        <slot name="global-nav"></slot>
        <slot name="first-local-nav"></slot>
        <slot name="second-local-nav"></slot>
        <main>
          <slot name="content"></slot>
        </main>
      </Host>
    );
  }
}
